static const z_t5779_t _zag1551 = { { .data = "win_close", .size = 9 }, { .length = 1, .data = _zag1550 }, { .length = 1, .data = _zag1526 }, { .data = "/* _close, its failure as a Win32 code: the C runtime keeps the OS's in\n   _doserrno when the OS refused, and only an errno when it refused itself */\nstatic int z_win_close(int fd) {\n    if (_close(fd) == 0) return 0;\n    DWORD e = (DWORD)_doserrno;\n    SetLastError(e != 0 ? e : z_win_from_errno(errno));\n    return -1;\n}", .size = 322 } };
